+
+static void _FWDownloadEnable(struct adapter *padapter, bool enable)
+{
+    u8 tmp, count = 0;
+
+    if (enable) {
+        /*  8051 enable */
+        tmp = rtw_read8(padapter, REG_SYS_FUNC_EN + 1);
+        rtw_write8(padapter, REG_SYS_FUNC_EN + 1, tmp | 0x04);
+
+        tmp = rtw_read8(padapter, REG_MCUFWDL);
+        rtw_write8(padapter, REG_MCUFWDL, tmp|0x01);
+
+        do {
+            tmp = rtw_read8(padapter, REG_MCUFWDL);
+            if (tmp & 0x01)
+                break;
+            rtw_write8(padapter, REG_MCUFWDL, tmp|0x01);
+            msleep(1);
+        } while (count++ < 100);
+
+        /*  8051 reset */
+        tmp = rtw_read8(padapter, REG_MCUFWDL+2);
+        rtw_write8(padapter, REG_MCUFWDL+2, tmp&0xf7);
+    } else {
+        /*  MCU firmware download disable. */
+        tmp = rtw_read8(padapter, REG_MCUFWDL);
+        rtw_write8(padapter, REG_MCUFWDL, tmp&0xfe);
+    }
+}
+
+static int _BlockWrite(struct adapter *padapter, void *buffer, u32 
buffSize)
+{
+    int ret = _SUCCESS;
+
+    u32 blockSize_p1 = 4; /*  (Default) Phase #1 : PCI muse use 4-byte 
write to download FW */
+    u32 blockSize_p2 = 8; /*  Phase #2 : Use 8-byte, if Phase#1 use big 
size to write FW. */
+    u32 blockSize_p3 = 1; /*  Phase #3 : Use 1-byte, the remnant of FW 
image. */
+    u32 blockCount_p1 = 0, blockCount_p2 = 0, blockCount_p3 = 0;
+    u32 remainSize_p1 = 0, remainSize_p2 = 0;
+    u8 *bufferPtr = buffer;
+    u32 i = 0, offset = 0;
+
+    /* 3 Phase #1 */
+    blockCount_p1 = buffSize / blockSize_p1;
+    remainSize_p1 = buffSize % blockSize_p1;
+
+    for (i = 0; i < blockCount_p1; i++) {
+        ret = rtw_write32(padapter, (FW_8723B_START_ADDRESS + i * 
blockSize_p1), *((u32 *)(bufferPtr + i * blockSize_p1)));
+        if (ret == _FAIL) {
+            netdev_dbg(padapter->pnetdev, "write failed at %s %d, 
block:%d\n",
+                   __func__, __LINE__, i);
+            goto exit;
+        }
+    }
+
+    /* 3 Phase #2 */
+    if (remainSize_p1) {
+        blockCount_p2 = remainSize_p1/blockSize_p2;
+        remainSize_p2 = remainSize_p1%blockSize_p2;
+    }
+
+    /* 3 Phase #3 */
+    if (remainSize_p2) {
+        offset = (blockCount_p1 * blockSize_p1) + (blockCount_p2 * 
blockSize_p2);
+
+        blockCount_p3 = remainSize_p2 / blockSize_p3;
+
+        for (i = 0; i < blockCount_p3; i++) {
+            ret = rtw_write8(padapter, (FW_8723B_START_ADDRESS + offset 
+ i), *(bufferPtr + offset + i));
+
+            if (ret == _FAIL) {
+                netdev_dbg(padapter->pnetdev, "write failed at %s %d, 
block:%d\n",
+                       __func__, __LINE__, i);
+                goto exit;
+            }
+        }
+    }
+exit:
+    return ret;
+}
+
+static int _PageWrite(
+    struct adapter *padapter,
+    u32 page,
+    void *buffer,
+    u32 size
+)
+{
+    u8 value8;
+    u8 u8Page = (u8) (page & 0x07);
+
+    value8 = (rtw_read8(padapter, REG_MCUFWDL+2) & 0xF8) | u8Page;
+    rtw_write8(padapter, REG_MCUFWDL+2, value8);
+
+    return _BlockWrite(padapter, buffer, size);
+}
+
+static int _WriteFW(struct adapter *padapter, void *buffer, u32 size)
+{
+    /*  Since we need dynamic decide method of dwonload fw, so we call 
this function to get chip version. */
+    /*  We can remove _ReadChipVersion from ReadpadapterInfo8192C 
later. */
+    int ret = _SUCCESS;
+    u32 pageNums, remainSize;
+    u32 page, offset;
+    u8 *bufferPtr = buffer;
+
+    pageNums = size / MAX_DLFW_PAGE_SIZE;
+    remainSize = size % MAX_DLFW_PAGE_SIZE;
+
+    for (page = 0; page < pageNums; page++) {
+        offset = page * MAX_DLFW_PAGE_SIZE;
+        ret = _PageWrite(padapter, page, bufferPtr+offset, 
MAX_DLFW_PAGE_SIZE);
+
+        if (ret == _FAIL) {
+            netdev_dbg(padapter->pnetdev, "page write failed at %s 
%d\n",
+                   __func__, __LINE__);
+            goto exit;
+        }
+    }
+
+    if (remainSize) {
+        offset = pageNums * MAX_DLFW_PAGE_SIZE;
+        page = pageNums;
+        ret = _PageWrite(padapter, page, bufferPtr+offset, remainSize);
+
+        if (ret == _FAIL) {
+            netdev_dbg(padapter->pnetdev, "remaining page write failed 
at %s %d\n",
+                   __func__, __LINE__);
+            goto exit;
+        }
+    }
+
+exit:
+    return ret;
+}
+
+void _8051Reset8723(struct adapter *padapter)
+{
+    u8 cpu_rst;
+    u8 io_rst;
+
+    /*  Reset 8051(WLMCU) IO wrapper */
+    /*  0x1c[8] = 0 */
+    /*  Suggested by Isaac@SD1 and Gimmy@SD1, coding by Lucas@20130624 
*/
+    io_rst = rtw_read8(padapter, REG_RSV_CTRL + 1);
+    io_rst &= ~BIT(0);
+    rtw_write8(padapter, REG_RSV_CTRL + 1, io_rst);
+
+    cpu_rst = rtw_read8(padapter, REG_SYS_FUNC_EN + 1);
+    cpu_rst &= ~BIT(2);
+    rtw_write8(padapter, REG_SYS_FUNC_EN + 1, cpu_rst);
+
+    /*  Enable 8051 IO wrapper */
+    /*  0x1c[8] = 1 */
+    io_rst = rtw_read8(padapter, REG_RSV_CTRL + 1);
+    io_rst |= BIT(0);
+    rtw_write8(padapter, REG_RSV_CTRL + 1, io_rst);
+
+    cpu_rst = rtw_read8(padapter, REG_SYS_FUNC_EN + 1);
+    cpu_rst |= BIT(2);
+    rtw_write8(padapter, REG_SYS_FUNC_EN + 1, cpu_rst);
+}
+
+u8 g_fwdl_chksum_fail;
+
+static s32 polling_fwdl_chksum(
+    struct adapter *adapter, u32 min_cnt, u32 timeout_ms
+)
+{
+    s32 ret = _FAIL;
+    u32 value32;
+    unsigned long start = jiffies;
+    u32 cnt = 0;
+
+    /* polling CheckSum report */
+    do {
+        cnt++;
+        value32 = rtw_read32(adapter, REG_MCUFWDL);
+        if (value32 & FWDL_ChkSum_rpt || adapter->bSurpriseRemoved ||
+            adapter->driver_stopped)
+            break;
+        yield();
+    } while (jiffies_to_msecs(jiffies-start) < timeout_ms || cnt < 
min_cnt);
+
+    if (!(value32 & FWDL_ChkSum_rpt))
+        goto exit;
+
+    if (g_fwdl_chksum_fail) {
+        g_fwdl_chksum_fail--;
+        goto exit;
+    }
+
+    ret = _SUCCESS;
+
+exit:
+
+    return ret;
+}
+
+u8 g_fwdl_wintint_rdy_fail;
+
+static s32 _FWFreeToGo(struct adapter *adapter, u32 min_cnt, u32 
timeout_ms)
+{
+    s32 ret = _FAIL;
+    u32 value32;
+    unsigned long start = jiffies;
+    u32 cnt = 0;
+
+    value32 = rtw_read32(adapter, REG_MCUFWDL);
+    value32 |= MCUFWDL_RDY;
+    value32 &= ~WINTINI_RDY;
+    rtw_write32(adapter, REG_MCUFWDL, value32);
+
+    _8051Reset8723(adapter);
+
+    /*  polling for FW ready */
+    do {
+        cnt++;
+        value32 = rtw_read32(adapter, REG_MCUFWDL);
+        if (value32 & WINTINI_RDY || adapter->bSurpriseRemoved || 
adapter->driver_stopped)
+            break;
+        yield();
+    } while (jiffies_to_msecs(jiffies - start) < timeout_ms || cnt < 
min_cnt);
+
+    if (!(value32 & WINTINI_RDY))
+        goto exit;
+
+    if (g_fwdl_wintint_rdy_fail) {
+        g_fwdl_wintint_rdy_fail--;
+        goto exit;
+    }
+
+    ret = _SUCCESS;
+
+exit:
+
+    return ret;
+}
+
+#define IS_FW_81xxC(padapter)    
(((GET_HAL_DATA(padapter))->FirmwareSignature & 0xFFF0) == 0x88C0)
+
+void rtl8723b_FirmwareSelfReset(struct adapter *padapter)
+{
+    struct hal_com_data *pHalData = GET_HAL_DATA(padapter);
+    u8 val;
+    u8 Delay = 100;
+
+    if (
+        !(IS_FW_81xxC(padapter) && ((pHalData->FirmwareVersion < 0x21) 
|| (pHalData->FirmwareVersion == 0x21 && pHalData->FirmwareSubVersion < 
0x01)))
+    ) { /*  after 88C Fw v33.1 */
+        /* 0x1cf = 0x20. Inform 8051 to reset. 2009.12.25. tynli_test 
*/
+        rtw_write8(padapter, REG_HMETFR+3, 0x20);
+
+        val = rtw_read8(padapter, REG_SYS_FUNC_EN + 1);
+        while (val & BIT(2)) {
+            Delay--;
+            if (Delay == 0)
+                break;
+            udelay(50);
+            val = rtw_read8(padapter, REG_SYS_FUNC_EN + 1);
+        }
+
+        if (Delay == 0) {
+            /* force firmware reset */
+            val = rtw_read8(padapter, REG_SYS_FUNC_EN + 1);
+            rtw_write8(padapter, REG_SYS_FUNC_EN + 1, val & (~BIT(2)));
+        }
+    }
+}
