+/*  */
+/*    Description: */
+/*        Download 8192C firmware code. */
+/*  */
+/*  */
+s32 rtl8723b_FirmwareDownload(struct adapter *padapter, bool  
bUsedWoWLANFw)
+{
+    s32 rtStatus = _SUCCESS;
+    u8 write_fw = 0;
+    unsigned long fwdl_start_time;
+    struct hal_com_data *pHalData = GET_HAL_DATA(padapter);
+    struct rt_firmware *pFirmware;
+    struct rt_firmware *pBTFirmware;
+    struct rt_firmware_hdr *pFwHdr = NULL;
+    u8 *pFirmwareBuf;
+    u32 FirmwareLen;
+    const struct firmware *fw;
+    struct device *device = dvobj_to_dev(padapter->dvobj);
+    u8 *fwfilepath;
+    u8 tmp_ps;
+
+    pFirmware = kzalloc_obj(struct rt_firmware);
+    if (!pFirmware)
+        return _FAIL;
+    pBTFirmware = kzalloc_obj(struct rt_firmware);
+    if (!pBTFirmware) {
+        kfree(pFirmware);
+        return _FAIL;
+    }
+    tmp_ps = rtw_read8(padapter, 0xa3);
+    tmp_ps &= 0xf8;
+    tmp_ps |= 0x02;
+    /* 1. write 0xA3[:2:0] = 3b'010 */
+    rtw_write8(padapter, 0xa3, tmp_ps);
+    /* 2. read power_state = 0xA0[1:0] */
+    tmp_ps = rtw_read8(padapter, 0xa0);
+    tmp_ps &= 0x03;
+
+    fwfilepath = "rtlwifi/rtl8723bs_nic.bin";
+
+    pr_info("rtl8723bs: acquire FW from file:%s\n", fwfilepath);
+
+    rtStatus = request_firmware(&fw, fwfilepath, device);
+    if (rtStatus) {
+        pr_err("Request firmware failed with error 0x%x\n", rtStatus);
+        rtStatus = _FAIL;
+        goto exit;
+    }
+
+    if (!fw) {
+        pr_err("Firmware %s not available\n", fwfilepath);
+        rtStatus = _FAIL;
+        goto exit;
+    }
+
+    if (fw->size > FW_8723B_SIZE) {
+        rtStatus = _FAIL;
+        release_firmware(fw);
+        goto exit;
+    }
+
+    pFirmware->fw_buffer_sz = kmemdup(fw->data, fw->size, GFP_KERNEL);
+    if (!pFirmware->fw_buffer_sz) {
+        rtStatus = _FAIL;
+        release_firmware(fw);
+        goto exit;
+    }
+
+    pFirmware->fw_length = fw->size;
+    release_firmware(fw);
+    if (pFirmware->fw_length > FW_8723B_SIZE) {
+        rtStatus = _FAIL;
+        netdev_emerg(padapter->pnetdev,
+                 "Firmware size:%u exceed %u\n",
+                 pFirmware->fw_length, FW_8723B_SIZE);
+        goto release_fw1;
+    }
+
+    pFirmwareBuf = pFirmware->fw_buffer_sz;
+    FirmwareLen = pFirmware->fw_length;
+
+    /*  To Check Fw header. Added by tynli. 2009.12.04. */
+    pFwHdr = (struct rt_firmware_hdr *)pFirmwareBuf;
+
+    pHalData->FirmwareVersion =  le16_to_cpu(pFwHdr->version);
+    pHalData->FirmwareSubVersion = le16_to_cpu(pFwHdr->subversion);
+    pHalData->FirmwareSignature = le16_to_cpu(pFwHdr->signature);
+
+    if (IS_FW_HEADER_EXIST_8723B(pFwHdr)) {
+        /*  Shift 32 bytes for FW header */
+        pFirmwareBuf = pFirmwareBuf + 32;
+        FirmwareLen = FirmwareLen - 32;
+    }
+
+    /*  Suggested by Filen. If 8051 is running in RAM code, driver 
should inform Fw to reset by itself, */
+    /*  or it will cause download Fw fail. 2010.02.01. by tynli. */
+    if (rtw_read8(padapter, REG_MCUFWDL) & RAM_DL_SEL) { /* 8051 RAM 
code */
+        rtw_write8(padapter, REG_MCUFWDL, 0x00);
+        rtl8723b_FirmwareSelfReset(padapter);
+    }
+
+    _FWDownloadEnable(padapter, true);
+    fwdl_start_time = jiffies;
+    while (
+        !padapter->driver_stopped &&
+        !padapter->bSurpriseRemoved &&
+        (write_fw++ < 3 || jiffies_to_msecs(jiffies - fwdl_start_time) 
< 500)
+    ) {
+        /* reset FWDL chksum */
+        rtw_write8(padapter, REG_MCUFWDL, rtw_read8(padapter, 
REG_MCUFWDL)|FWDL_ChkSum_rpt);
+
+        rtStatus = _WriteFW(padapter, pFirmwareBuf, FirmwareLen);
+        if (rtStatus != _SUCCESS)
+            continue;
+
+        rtStatus = polling_fwdl_chksum(padapter, 5, 50);
+        if (rtStatus == _SUCCESS)
+            break;
+    }
+    _FWDownloadEnable(padapter, false);
+    if (rtStatus != _SUCCESS)
+        goto fwdl_stat;
+
+    rtStatus = _FWFreeToGo(padapter, 10, 200);
+    if (rtStatus != _SUCCESS)
+        goto fwdl_stat;
+
+fwdl_stat:
+
+exit:
+    kfree(pFirmware->fw_buffer_sz);
+    kfree(pFirmware);
+release_fw1:
+    kfree(pBTFirmware);
+    return rtStatus;
+}
