+void rtl8723b_InitBeaconParameters(struct adapter *padapter)
+{
+    struct hal_com_data *pHalData = GET_HAL_DATA(padapter);
+    u16 val16;
+    u8 val8 = DIS_TSF_UDT;
+
+    val16 = val8 | (val8 << 8); /*  port0 and port1 */
+
+    /*  Enable prot0 beacon function for PSTDMA */
+    val16 |= EN_BCN_FUNCTION;
+
+    rtw_write16(padapter, REG_BCN_CTRL, val16);
+
+    rtw_write16(padapter, REG_TBTT_PROHIBIT, TBTT_PROHIBIT_TIME_8723B);
+    /*  Firmware will control REG_DRVERLYINT when power saving is 
enable, */
+    /*  so don't set this register on STA mode. */
+    if (!check_fwstate(&padapter->mlmepriv, WIFI_STATION_STATE))
+        rtw_write8(padapter, REG_DRVERLYINT, 
DRIVER_EARLY_INT_TIME_8723B); /*  5ms */
+    rtw_write8(padapter, REG_BCNDMATIM, BCN_DMA_ATIME_INT_TIME_8723B); 
/*  2ms */
+
+    /*  Suggested by designer timchen. Change beacon AIFS to the 
largest number */
+    /*  because test chip does not contension before sending beacon. by 
tynli. 2009.11.03 */
+    rtw_write16(padapter, REG_BCNTCFG, BCNTCFG_8723B);
+
+    pHalData->RegFwHwTxQCtrl = rtw_read8(padapter, 
REG_FWHW_TXQ_CTRL+2);
+    pHalData->RegReg542 = rtw_read8(padapter, REG_TBTT_PROHIBIT+2);
+}
+
+void _InitBurstPktLen_8723BS(struct adapter *Adapter)
+{
+    struct hal_com_data *pHalData = GET_HAL_DATA(Adapter);
+
+    rtw_write8(Adapter, 0x4c7, rtw_read8(Adapter, 0x4c7)|BIT(7)); /* 
enable single pkt ampdu */
+    rtw_write8(Adapter, REG_RX_PKT_LIMIT_8723B, 0x18);        /* for 
VHT packet length 11K */
+    rtw_write8(Adapter, REG_MAX_AGGR_NUM_8723B, 0x1F);
+    rtw_write8(Adapter, REG_PIFS_8723B, 0x00);
+    rtw_write8(Adapter, REG_FWHW_TXQ_CTRL_8723B, rtw_read8(Adapter, 
REG_FWHW_TXQ_CTRL)&(~BIT(7)));
+    if (pHalData->AMPDUBurstMode)
+        rtw_write8(Adapter, REG_AMPDU_BURST_MODE_8723B,  0x5F);
+    rtw_write8(Adapter, REG_AMPDU_MAX_TIME_8723B, 0x70);
+
+    /*  ARFB table 9 for 11ac 5G 2SS */
+    rtw_write32(Adapter, REG_ARFR0_8723B, 0x00000010);
+    if (pHalData->chip_normal)
+        rtw_write32(Adapter, REG_ARFR0_8723B+4, 0xfffff000);
+    else
+        rtw_write32(Adapter, REG_ARFR0_8723B+4, 0x3e0ff000);
+
+    /*  ARFB table 10 for 11ac 5G 1SS */
+    rtw_write32(Adapter, REG_ARFR1_8723B, 0x00000010);
+    rtw_write32(Adapter, REG_ARFR1_8723B+4, 0x003ff000);
+}
+
+static void ResumeTxBeacon(struct adapter *padapter)
+{
+    struct hal_com_data *pHalData = GET_HAL_DATA(padapter);
+
+    pHalData->RegFwHwTxQCtrl |= BIT(6);
+    rtw_write8(padapter, REG_FWHW_TXQ_CTRL+2, 
pHalData->RegFwHwTxQCtrl);
+    rtw_write8(padapter, REG_TBTT_PROHIBIT+1, 0xff);
+    pHalData->RegReg542 |= BIT(0);
+    rtw_write8(padapter, REG_TBTT_PROHIBIT+2, pHalData->RegReg542);
+}
+
+static void StopTxBeacon(struct adapter *padapter)
+{
+    struct hal_com_data *pHalData = GET_HAL_DATA(padapter);
+
+    pHalData->RegFwHwTxQCtrl &= ~BIT(6);
+    rtw_write8(padapter, REG_FWHW_TXQ_CTRL+2, 
pHalData->RegFwHwTxQCtrl);
+    rtw_write8(padapter, REG_TBTT_PROHIBIT+1, 0x64);
+    pHalData->RegReg542 &= ~BIT(0);
+    rtw_write8(padapter, REG_TBTT_PROHIBIT+2, pHalData->RegReg542);
+}
+
+static void _BeaconFunctionEnable(struct adapter *padapter, u8 Enable, 
u8 Linked)
+{
+    rtw_write8(padapter, REG_BCN_CTRL, DIS_TSF_UDT | EN_BCN_FUNCTION | 
DIS_BCNQ_SUB);
+    rtw_write8(padapter, REG_RD_CTRL+1, 0x6F);
+}
+
+void rtl8723b_SetBeaconRelatedRegisters(struct adapter *padapter)
+{
+    u8 val8;
+    u32 value32;
+    struct mlme_ext_priv *pmlmeext = &padapter->mlmeextpriv;
+    struct mlme_ext_info *pmlmeinfo = &pmlmeext->mlmext_info;
+    u32 bcn_ctrl_reg;
+
+    /* reset TSF, enable update TSF, correcting TSF On Beacon */
+
+    /* REG_BCN_INTERVAL */
+    /* REG_BCNDMATIM */
+    /* REG_ATIMWND */
+    /* REG_TBTT_PROHIBIT */
+    /* REG_DRVERLYINT */
+    /* REG_BCN_MAX_ERR */
+    /* REG_BCNTCFG (0x510) */
+    /* REG_DUAL_TSF_RST */
+    /* REG_BCN_CTRL (0x550) */
+
+    bcn_ctrl_reg = REG_BCN_CTRL;
+
+    /*  */
+    /*  ATIM window */
+    /*  */
+    rtw_write16(padapter, REG_ATIMWND, 2);
+
+    /*  */
+    /*  Beacon interval (in unit of TU). */
+    /*  */
+    rtw_write16(padapter, REG_BCN_INTERVAL, pmlmeinfo->bcn_interval);
+
+    rtl8723b_InitBeaconParameters(padapter);
+
+    rtw_write8(padapter, REG_SLOT, 0x09);
+
+    /*  */
+    /*  Reset TSF Timer to zero, added by Roger. 2008.06.24 */
+    /*  */
+    value32 = rtw_read32(padapter, REG_TCR);
+    value32 &= ~TSFRST;
+    rtw_write32(padapter, REG_TCR, value32);
+
+    value32 |= TSFRST;
+    rtw_write32(padapter, REG_TCR, value32);
+
+    /*  NOTE: Fix test chip's bug (about contention windows's 
randomness) */
+    if (check_fwstate(&padapter->mlmepriv, WIFI_ADHOC_STATE |
+                           WIFI_ADHOC_MASTER_STATE | WIFI_AP_STATE)) {
+        rtw_write8(padapter, REG_RXTSF_OFFSET_CCK, 0x50);
+        rtw_write8(padapter, REG_RXTSF_OFFSET_OFDM, 0x50);
+    }
+
+    _BeaconFunctionEnable(padapter, true, true);
+
+    ResumeTxBeacon(padapter);
+    val8 = rtw_read8(padapter, bcn_ctrl_reg);
+    val8 |= DIS_BCNQ_SUB;
+    rtw_write8(padapter, bcn_ctrl_reg, val8);
+}
