+void Hal_EfuseParseTxPowerInfo_8723B(
+    struct adapter *padapter, u8 *PROMContent, bool AutoLoadFail
+)
+{
+    struct hal_com_data    *pHalData = GET_HAL_DATA(padapter);
+    struct TxPowerInfo24G    pwrInfo24G;
+    u8    rfPath, ch, TxCount = 1;
+
+    Hal_ReadPowerValueFromPROM_8723B(padapter, &pwrInfo24G, 
PROMContent, AutoLoadFail);
+    for (rfPath = 0 ; rfPath < MAX_RF_PATH ; rfPath++) {
+        for (ch = 0 ; ch < CHANNEL_MAX_NUMBER; ch++) {
+            u8 group = 0;
+
+            hal_get_chnl_group_8723b(ch + 1, &group);
+
+            if (ch == 14-1) {
+                pHalData->Index24G_CCK_Base[rfPath][ch] = 
pwrInfo24G.IndexCCK_Base[rfPath][5];
+                pHalData->Index24G_BW40_Base[rfPath][ch] = 
pwrInfo24G.IndexBW40_Base[rfPath][group];
+            } else {
+                pHalData->Index24G_CCK_Base[rfPath][ch] = 
pwrInfo24G.IndexCCK_Base[rfPath][group];
+                pHalData->Index24G_BW40_Base[rfPath][ch] = 
pwrInfo24G.IndexBW40_Base[rfPath][group];
+            }
+        }
+
+        for (TxCount = 0; TxCount < MAX_TX_COUNT; TxCount++) {
+            pHalData->OFDM_24G_Diff[rfPath][TxCount] = 
pwrInfo24G.OFDM_Diff[rfPath][TxCount];
+            pHalData->BW20_24G_Diff[rfPath][TxCount] = 
pwrInfo24G.BW20_Diff[rfPath][TxCount];
+            pHalData->BW40_24G_Diff[rfPath][TxCount] = 
pwrInfo24G.BW40_Diff[rfPath][TxCount];
+        }
+    }
+
+    /*  2010/10/19 MH Add Regulator recognize for CU. */
+    if (!AutoLoadFail) {
+        pHalData->EEPROMRegulatory = 
(PROMContent[EEPROM_RF_BOARD_OPTION_8723B]&0x7);    /* bit0~2 */
+        if (PROMContent[EEPROM_RF_BOARD_OPTION_8723B] == 0xFF)
+            pHalData->EEPROMRegulatory = 
(EEPROM_DEFAULT_BOARD_OPTION&0x7);    /* bit0~2 */
+    } else
+        pHalData->EEPROMRegulatory = 0;
+}
