+static void rtl8723b_fill_default_txdesc(
+    struct xmit_frame *pxmitframe, u8 *pbuf
+)
+{
+    struct adapter *padapter;
+    struct hal_com_data *pHalData;
+    struct mlme_ext_priv *pmlmeext;
+    struct mlme_ext_info *pmlmeinfo;
+    struct pkt_attrib *pattrib;
+    struct txdesc_8723b *ptxdesc;
+    s32 bmcst;
+
+    memset(pbuf, 0, TXDESC_SIZE);
+
+    padapter = pxmitframe->padapter;
+    pHalData = GET_HAL_DATA(padapter);
+    pmlmeext = &padapter->mlmeextpriv;
+    pmlmeinfo = &(pmlmeext->mlmext_info);
+
+    pattrib = &pxmitframe->attrib;
+    bmcst = is_multicast_ether_addr(pattrib->ra);
+
+    ptxdesc = (struct txdesc_8723b *)pbuf;
+
+    if (pxmitframe->frame_tag == DATA_FRAMETAG) {
+        u8 drv_userate = 0;
+
+        ptxdesc->macid = pattrib->mac_id; /*  CAM_ID(MAC_ID) */
+        ptxdesc->rate_id = pattrib->raid;
+        ptxdesc->qsel = pattrib->qsel;
+        ptxdesc->seq = pattrib->seqnum;
+
+        ptxdesc->sectype = fill_txdesc_sectype(pattrib);
+        fill_txdesc_vcs_8723b(padapter, pattrib, ptxdesc);
+
+        if (pattrib->icmp_pkt == 1 && padapter->registrypriv.wifi_spec 
== 1)
+            drv_userate = 1;
+
+        if (
+            (pattrib->ether_type != 0x888e) &&
+            (pattrib->ether_type != 0x0806) &&
+            (pattrib->ether_type != 0x88B4) &&
+            (pattrib->dhcp_pkt != 1) &&
+            (drv_userate != 1)
+        ) {
+            /*  Non EAP & ARP & DHCP type data packet */
+
+            if (pattrib->ampdu_en) {
+                ptxdesc->agg_en = 1; /*  AGG EN */
+                ptxdesc->max_agg_num = 0x1f;
+                ptxdesc->ampdu_density = pattrib->ampdu_spacing;
+            } else
+                ptxdesc->bk = 1; /*  AGG BK */
+
+            fill_txdesc_phy_8723b(padapter, pattrib, ptxdesc);
+
+            ptxdesc->data_ratefb_lmt = 0x1F;
+
+            if (!pHalData->fw_ractrl) {
+                ptxdesc->userate = 1;
+
+                if (pHalData->dmpriv.INIDATA_RATE[pattrib->mac_id] & 
BIT(7))
+                    ptxdesc->data_short = 1;
+
+                ptxdesc->datarate = 
pHalData->dmpriv.INIDATA_RATE[pattrib->mac_id] & 0x7F;
+            }
+
+            if (padapter->fix_rate != 0xFF) { /*  modify data rate by 
iwpriv */
+                ptxdesc->userate = 1;
+                if (padapter->fix_rate & BIT(7))
+                    ptxdesc->data_short = 1;
+
+                ptxdesc->datarate = (padapter->fix_rate & 0x7F);
+                ptxdesc->disdatafb = 1;
+            }
+
+            if (pattrib->ldpc)
+                ptxdesc->data_ldpc = 1;
+            if (pattrib->stbc)
+                ptxdesc->data_stbc = 1;
+        } else {
+            /*  EAP data packet and ARP packet. */
+            /*  Use the 1M data rate to send the EAP/ARP packet. */
+            /*  This will maybe make the handshake smooth. */
+
+            ptxdesc->bk = 1; /*  AGG BK */
+            ptxdesc->userate = 1; /*  driver uses rate */
+            if (pmlmeinfo->preamble_mode == PREAMBLE_SHORT)
+                ptxdesc->data_short = 1;/*  DATA_SHORT */
+            ptxdesc->datarate = MRateToHwRate(pmlmeext->tx_rate);
+        }
+
+        ptxdesc->usb_txagg_num = pxmitframe->agg_num;
+    } else if (pxmitframe->frame_tag == MGNT_FRAMETAG) {
+        ptxdesc->macid = pattrib->mac_id; /*  CAM_ID(MAC_ID) */
+        ptxdesc->qsel = pattrib->qsel;
+        ptxdesc->rate_id = pattrib->raid; /*  Rate ID */
+        ptxdesc->seq = pattrib->seqnum;
+        ptxdesc->userate = 1; /*  driver uses rate, 1M */
+
+        ptxdesc->mbssid = pattrib->mbssid & 0xF;
+
+        ptxdesc->rty_lmt_en = 1; /*  retry limit enable */
+        if (pattrib->retry_ctrl) {
+            ptxdesc->data_rt_lmt = 6;
+        } else {
+            ptxdesc->data_rt_lmt = 12;
+        }
+
+        ptxdesc->datarate = MRateToHwRate(pmlmeext->tx_rate);
+
+        /*  CCX-TXRPT ack for xmit mgmt frames. */
+        if (pxmitframe->ack_report) {
+            ptxdesc->spe_rpt = 1;
+            ptxdesc->sw_define = 
(u8)(GET_PRIMARY_ADAPTER(padapter)->xmitpriv.seq_no);
+        }
+    } else {
+        ptxdesc->macid = pattrib->mac_id; /*  CAM_ID(MAC_ID) */
+        ptxdesc->rate_id = pattrib->raid; /*  Rate ID */
+        ptxdesc->qsel = pattrib->qsel;
+        ptxdesc->seq = pattrib->seqnum;
+        ptxdesc->userate = 1; /*  driver uses rate */
+        ptxdesc->datarate = MRateToHwRate(pmlmeext->tx_rate);
+    }
+
+    ptxdesc->pktlen = pattrib->last_txcmdsz;
+    ptxdesc->offset = TXDESC_SIZE + OFFSET_SZ;
+
+    if (bmcst)
+        ptxdesc->bmc = 1;
+
+    /* 2009.11.05. tynli_test. Suggested by SD4 Filen for FW LPS.
+     * (1) The sequence number of each non-Qos frame / broadcast /
+     * multicast / mgnt frame should be controlled by Hw because Fw
+     * will also send null data which we cannot control when Fw LPS
+     * enable.
+     * --> default enable non-Qos data sequence number. 2010.06.23.
+     * by tynli.
+     * (2) Enable HW SEQ control for beacon packet, because we use
+     * Hw beacon.
+     * (3) Use HW Qos SEQ to control the seq num of Ext port non-Qos
+     * packets.
+     * 2010.06.23. Added by tynli.
+     */
+    if (!pattrib->qos_en) /*  Hw set sequence number */
+        ptxdesc->en_hwseq = 1; /*  HWSEQ_EN */
+}
+
+/* Description:
+ *
+ * Parameters:
+ *    pxmitframe    xmitframe
+ *    pbuf        where to fill tx desc
+ */
+void rtl8723b_update_txdesc(struct xmit_frame *pxmitframe, u8 *pbuf)
+{
+    struct tx_desc *pdesc;
+
+    rtl8723b_fill_default_txdesc(pxmitframe, pbuf);
+    pdesc = (struct tx_desc *)pbuf;
+    rtl8723b_cal_txdesc_chksum(pdesc);
+}
+
+/*  */
+/*  Description: In normal chip, we should send some packet to Hw which 
will be used by Fw */
+/*            in FW LPS mode. The function is to fill the Tx descriptor 
of this packets, then */
+/*            Fw can tell Hw to send these packet derectly. */
+/*  Added by tynli. 2009.10.15. */
+/*  */
+/* type1:pspoll, type2:null */
+void rtl8723b_fill_fake_txdesc(
+    struct adapter *padapter,
+    u8 *pDesc,
+    u32 BufferLen,
+    u8 IsPsPoll,
+    u8 IsBTQosNull,
+    u8 bDataFrame
+)
+{
+    /*  Clear all status */
+    memset(pDesc, 0, TXDESC_SIZE);
+
+    SET_TX_DESC_FIRST_SEG_8723B(pDesc, 1); /* bFirstSeg; */
+    SET_TX_DESC_LAST_SEG_8723B(pDesc, 1); /* bLastSeg; */
+
+    SET_TX_DESC_OFFSET_8723B(pDesc, 0x28); /*  Offset = 32 */
+
+    SET_TX_DESC_PKT_SIZE_8723B(pDesc, BufferLen); /*  Buffer size + 
command header */
+    SET_TX_DESC_QUEUE_SEL_8723B(pDesc, QSLT_MGNT); /*  Fixed queue of 
Mgnt queue */
+
+    /*  Set NAVUSEHDR to prevent Ps-poll AId filed to be changed to 
error value by Hw. */
+    if (IsPsPoll) {
+        SET_TX_DESC_NAV_USE_HDR_8723B(pDesc, 1);
+    } else {
+        SET_TX_DESC_HWSEQ_EN_8723B(pDesc, 1); /*  Hw set sequence 
number */
+        SET_TX_DESC_HWSEQ_SEL_8723B(pDesc, 0);
+    }
+
+    if (IsBTQosNull)
+        SET_TX_DESC_BT_INT_8723B(pDesc, 1);
+
+    SET_TX_DESC_USE_RATE_8723B(pDesc, 1); /*  use data rate which is 
set by Sw */
+    SET_TX_DESC_OWN_8723B((u8 *)pDesc, 1);
+
+    SET_TX_DESC_TX_RATE_8723B(pDesc, DESC8723B_RATE1M);
+
+    /*  */
+    /*  Encrypt the data frame if under security mode excepct null 
data. Suggested by CCW. */
+    /*  */
+    if (bDataFrame) {
+        u32 EncAlg = padapter->securitypriv.dot11_privacy_algrthm;
+
+        switch (EncAlg) {
+        case _NO_PRIVACY_:
+            SET_TX_DESC_SEC_TYPE_8723B(pDesc, 0x0);
+            break;
+        case _WEP40_:
+        case _WEP104_:
+        case _TKIP_:
+            SET_TX_DESC_SEC_TYPE_8723B(pDesc, 0x1);
+            break;
+        case _SMS4_:
+            SET_TX_DESC_SEC_TYPE_8723B(pDesc, 0x2);
+            break;
+        case _AES_:
+            SET_TX_DESC_SEC_TYPE_8723B(pDesc, 0x3);
+            break;
+        default:
+            SET_TX_DESC_SEC_TYPE_8723B(pDesc, 0x0);
+            break;
+        }
+    }
+
+    /*  USB interface drop packet if the checksum of descriptor isn't 
correct. */
+    /*  Using this checksum can let hardware recovery from packet bulk 
out error (e.g. Cancel URC, Bulk out error.). */
+    rtl8723b_cal_txdesc_chksum((struct tx_desc *)pDesc);
+}
