+static void hw_var_set_macaddr(struct adapter *padapter, u8 variable, 
u8 *val)
+{
+    u8 idx = 0;
+    u32 reg_macid = REG_MACID;
+
+    for (idx = 0 ; idx < 6; idx++)
+        rtw_write8(GET_PRIMARY_ADAPTER(padapter), (reg_macid+idx), 
val[idx]);
