+static void hw_var_set_correct_tsf(struct adapter *padapter, u8 
variable, u8 *val)
+{
+    u8 val8;
+    u64 tsf;
+    struct mlme_ext_priv *pmlmeext = &padapter->mlmeextpriv;
+    struct mlme_ext_info *pmlmeinfo = &pmlmeext->mlmext_info;
+
+    tsf = pmlmeext->TSFValue-do_div(pmlmeext->TSFValue, 
(pmlmeinfo->bcn_interval*1024))-1024; /* us */
+
+    if (
+        ((pmlmeinfo->state&0x03) == WIFI_FW_ADHOC_STATE) ||
+        ((pmlmeinfo->state&0x03) == WIFI_FW_AP_STATE)
+    )
+        StopTxBeacon(padapter);
+
+    {
+        /*  disable related TSF function */
+        val8 = rtw_read8(padapter, REG_BCN_CTRL);
+        val8 &= ~EN_BCN_FUNCTION;
+        rtw_write8(padapter, REG_BCN_CTRL, val8);
+
+        rtw_write32(padapter, REG_TSFTR, tsf);
+        rtw_write32(padapter, REG_TSFTR+4, tsf>>32);
+
+        /*  enable related TSF function */
+        val8 = rtw_read8(padapter, REG_BCN_CTRL);
+        val8 |= EN_BCN_FUNCTION;
+        rtw_write8(padapter, REG_BCN_CTRL, val8);
+    }
+
+    if (
+        ((pmlmeinfo->state&0x03) == WIFI_FW_ADHOC_STATE) ||
+        ((pmlmeinfo->state&0x03) == WIFI_FW_AP_STATE)
+    )
+        ResumeTxBeacon(padapter);
+}
+
+static void hw_var_set_mlme_disconnect(struct adapter *padapter, u8 
variable, u8 *val)
+{
+    u8 val8;
+
+    /*  Set RCR to not to receive data frame when NO LINK state */
+    /* rtw_write32(padapter, REG_RCR, rtw_read32(padapter, REG_RCR) & 
~RCR_ADF); */
+    /*  reject all data frames */
+    rtw_write16(padapter, REG_RXFLTMAP2, 0);
+
+    /*  reset TSF */
+    rtw_write8(padapter, REG_DUAL_TSF_RST, BIT(0));
+
+    /*  disable update TSF */
+    val8 = rtw_read8(padapter, REG_BCN_CTRL);
+    val8 |= DIS_TSF_UDT;
+    rtw_write8(padapter, REG_BCN_CTRL, val8);
+}
+
+static void hw_var_set_mlme_sitesurvey(struct adapter *padapter, u8 
variable, u8 *val)
+{
+    u32 value_rcr, rcr_clear_bit, reg_bcn_ctl;
+    u16 value_rxfltmap2;
+    u8 val8;
+    struct hal_com_data *pHalData;
+    struct mlme_priv *pmlmepriv;
+
+    pHalData = GET_HAL_DATA(padapter);
+    pmlmepriv = &padapter->mlmepriv;
+
+    reg_bcn_ctl = REG_BCN_CTRL;
+
+    rcr_clear_bit = RCR_CBSSID_BCN;
+
+    /*  config RCR to receive different BSSID & not to receive data 
frame */
+    value_rxfltmap2 = 0;
+
+    if (check_fwstate(pmlmepriv, WIFI_AP_STATE))
+        rcr_clear_bit = RCR_CBSSID_BCN;
+
+    value_rcr = rtw_read32(padapter, REG_RCR);
+
+    if (*((u8 *)val)) {
+        /*  under sitesurvey */
+        value_rcr &= ~(rcr_clear_bit);
+        rtw_write32(padapter, REG_RCR, value_rcr);
+
+        rtw_write16(padapter, REG_RXFLTMAP2, value_rxfltmap2);
+
+        if (check_fwstate(pmlmepriv, WIFI_STATION_STATE | 
WIFI_ADHOC_STATE | WIFI_ADHOC_MASTER_STATE)) {
+            /*  disable update TSF */
+            val8 = rtw_read8(padapter, reg_bcn_ctl);
+            val8 |= DIS_TSF_UDT;
+            rtw_write8(padapter, reg_bcn_ctl, val8);
+        }
+
+        /*  Save original RRSR setting. */
+        pHalData->RegRRSR = rtw_read16(padapter, REG_RRSR);
+    } else {
+        /*  sitesurvey done */
+        if (check_fwstate(pmlmepriv, (_FW_LINKED|WIFI_AP_STATE)))
+            /*  enable to rx data frame */
+            rtw_write16(padapter, REG_RXFLTMAP2, 0xFFFF);
+
+        if (check_fwstate(pmlmepriv, WIFI_STATION_STATE | 
WIFI_ADHOC_STATE | WIFI_ADHOC_MASTER_STATE)) {
+            /*  enable update TSF */
+            val8 = rtw_read8(padapter, reg_bcn_ctl);
+            val8 &= ~DIS_TSF_UDT;
+            rtw_write8(padapter, reg_bcn_ctl, val8);
+        }
+
+        value_rcr |= rcr_clear_bit;
+        rtw_write32(padapter, REG_RCR, value_rcr);
+
+        /*  Restore original RRSR setting. */
+        rtw_write16(padapter, REG_RRSR, pHalData->RegRRSR);
+    }
+}
+
+static void hw_var_set_mlme_join(struct adapter *padapter, u8 variable, 
u8 *val)
+{
+    u8 val8;
+    u16 val16;
+    u32 val32;
+    u8 RetryLimit = 0x30;
+    u8 type = *(u8 *)val;
+    struct mlme_priv *pmlmepriv = &padapter->mlmepriv;
+    struct eeprom_priv *pEEPROM;
+
+    pEEPROM = GET_EEPROM_EFUSE_PRIV(padapter);
+
+    if (type == 0) { /*  prepare to join */
+        /* enable to rx data frame.Accept all data frame */
+        /* rtw_write32(padapter, REG_RCR, rtw_read32(padapter, 
REG_RCR)|RCR_ADF); */
+        rtw_write16(padapter, REG_RXFLTMAP2, 0xFFFF);
+
+        val32 = rtw_read32(padapter, REG_RCR);
+        if (padapter->in_cta_test)
+            val32 &= ~(RCR_CBSSID_DATA | RCR_CBSSID_BCN);/*  RCR_ADF */
+        else
+            val32 |= RCR_CBSSID_DATA|RCR_CBSSID_BCN;
+        rtw_write32(padapter, REG_RCR, val32);
+
+        if (check_fwstate(pmlmepriv, WIFI_STATION_STATE))
+            RetryLimit = (pEEPROM->CustomerID == RT_CID_CCX) ? 7 : 48;
+        else /*  Ad-hoc Mode */
+            RetryLimit = 0x7;
+    } else if (type == 1) /* joinbss_event call back when join res < 0 
*/
+        rtw_write16(padapter, REG_RXFLTMAP2, 0x00);
+    else if (type == 2) { /* sta add event call back */
+        /* enable update TSF */
+        val8 = rtw_read8(padapter, REG_BCN_CTRL);
+        val8 &= ~DIS_TSF_UDT;
+        rtw_write8(padapter, REG_BCN_CTRL, val8);
+
+        if (check_fwstate(pmlmepriv, 
WIFI_ADHOC_STATE|WIFI_ADHOC_MASTER_STATE))
+            RetryLimit = 0x7;
+    }
+
+    val16 = (RetryLimit << RETRY_LIMIT_SHORT_SHIFT) | (RetryLimit << 
RETRY_LIMIT_LONG_SHIFT);
+    rtw_write16(padapter, REG_RL, val16);
+}
+
+void CCX_FwC2HTxRpt_8723b(struct adapter *padapter, u8 *pdata, u8 len)
+{
